-- ESQUEMA EXCLUSIVO DOS TESTES; nunca executar no Neon existente.
CREATE TABLE usuarios (id_usuario integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome varchar(100) NOT NULL,email varchar(254) NOT NULL UNIQUE,senha_hash varchar(255) NOT NULL,status varchar(30) NOT NULL,data_cadastro timestamp,ultimo_acesso timestamp);
CREATE TABLE clientes (id_cliente integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_usuario integer NOT NULL UNIQUE REFERENCES usuarios(id_usuario),cpf varchar,telefone varchar,data_nascimento date);
CREATE TABLE categorias (id_categoria integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome varchar NOT NULL,descricao text,status varchar);
CREATE TABLE produtos (id_produto integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_categoria integer NOT NULL REFERENCES categorias(id_categoria),nome varchar NOT NULL,descricao text,preco numeric(12,2) NOT NULL CHECK(preco>=0),estoque integer NOT NULL CHECK(estoque>=0),imagem varchar,status varchar,data_cadastro timestamp);
CREATE TABLE enderecos (id_endereco integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_cliente integer NOT NULL REFERENCES clientes(id_cliente),cep varchar NOT NULL,logradouro varchar NOT NULL,numero varchar,complemento varchar,bairro varchar,cidade varchar NOT NULL,estado varchar NOT NULL,tipo varchar,principal boolean);
CREATE TABLE pedidos (id_pedido integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_cliente integer NOT NULL REFERENCES clientes(id_cliente),id_endereco_entrega integer NOT NULL REFERENCES enderecos(id_endereco),data_pedido timestamp,status varchar,valor_total numeric NOT NULL);
CREATE TABLE itens_pedido (id_item integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_pedido integer NOT NULL REFERENCES pedidos(id_pedido),id_produto integer NOT NULL REFERENCES produtos(id_produto),quantidade integer NOT NULL,preco_unitario numeric NOT NULL,subtotal numeric NOT NULL);
CREATE TABLE pagamentos (id_pagamento integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_pedido integer NOT NULL REFERENCES pedidos(id_pedido),metodo varchar NOT NULL,valor numeric NOT NULL,status varchar,data_pagamento timestamp,codigo_transacao varchar);
